import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUserListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserListUser";

export async function test_api_user_token_refresh(connection: api.IConnection) {
  // Step 1: Register a new user to obtain initial tokens
  const joinInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password123",
  } satisfies ITodoListUserListUser.IJoin;

  const joinResponse = await api.functional.auth.user.join(connection, {
    body: joinInput,
  });
  typia.assert(joinResponse);

  // Store the initial tokens for later comparison
  const initialAccessToken = joinResponse.token.access;
  const initialRefreshToken = joinResponse.token.refresh;
  const initialExpiredAt = joinResponse.token.expired_at;
  const initialRefreshableUntil = joinResponse.token.refreshable_until;

  // Step 2: Use the refresh token to get new tokens
  // Create a new connection with the refresh token in the Authorization header
  const refreshConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: `Bearer ${initialRefreshToken}`,
    },
  };

  const refreshResponse =
    await api.functional.auth.user.refresh(refreshConnection);
  typia.assert(refreshResponse);

  // Step 3: Validate that new tokens are different from the initial ones
  TestValidator.notEquals(
    "new access token should be different",
    refreshResponse.token.access,
    initialAccessToken,
  );

  TestValidator.notEquals(
    "new refresh token should be different",
    refreshResponse.token.refresh,
    initialRefreshToken,
  );

  // Step 4: Validate that the new tokens have proper expiration timestamps
  TestValidator.predicate("access token should have future expiration", () => {
    const expiredAt = new Date(refreshResponse.token.expired_at);
    return expiredAt > new Date();
  });

  TestValidator.predicate("refresh token should have future expiration", () => {
    const refreshableUntil = new Date(refreshResponse.token.refreshable_until);
    return refreshableUntil > new Date();
  });

  // Step 5: Validate that the refreshed tokens belong to the same user
  TestValidator.equals(
    "refreshed user ID should match original",
    refreshResponse.id,
    joinResponse.id,
  );

  TestValidator.equals(
    "refreshed user email should match original",
    refreshResponse.email,
    joinResponse.email,
  );

  // Step 6: Verify that the connection now has the new access token
  TestValidator.equals(
    "connection should have new access token",
    refreshConnection.headers?.Authorization,
    `Bearer ${refreshResponse.token.access}`,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUserListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserListUser";
import type { ITodoListUserTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserTodo";

export async function test_api_todo_creation_by_user(
  connection: api.IConnection,
) {
  // Step 1: Register a new user to get authentication tokens
  const joinInput = {
    email: `${RandomGenerator.alphabets(10)}@test.com`,
    password: "password123",
  } satisfies ITodoListUserListUser.IJoin;

  const userAuth: ITodoListUserListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: joinInput,
    });
  typia.assert(userAuth);

  // Step 2: Create a new todo item using the authenticated user's credentials
  const todoInput = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies ITodoListUserTodo.ICreate;

  const createdTodo: ITodoListUserTodo =
    await api.functional.todoList.user.users.todos.create(connection, {
      userId: userAuth.id,
      body: todoInput,
    });
  typia.assert(createdTodo);

  // Step 3: Validate the response contains the correct todo item properties
  TestValidator.equals(
    "todo ID should be a valid UUID",
    typeof createdTodo.id,
    "string",
  );
  TestValidator.predicate("todo ID should match UUID format", () =>
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
      createdTodo.id,
    ),
  );
  TestValidator.equals(
    "todo title should match input",
    createdTodo.title,
    todoInput.title,
  );
  TestValidator.equals(
    "todo should not be completed by default",
    createdTodo.completed,
    false,
  );
  TestValidator.equals(
    "todo user ID should match authenticated user",
    createdTodo.todo_list_user_id,
    userAuth.id,
  );
  TestValidator.equals(
    "todo description should be undefined by default",
    createdTodo.description,
    undefined,
  );
  TestValidator.predicate(
    "todo should have creation timestamp",
    () =>
      createdTodo.created_at !== undefined && createdTodo.created_at.length > 0,
  );
  TestValidator.predicate(
    "todo should have update timestamp",
    () =>
      createdTodo.updated_at !== undefined && createdTodo.updated_at.length > 0,
  );
  TestValidator.predicate(
    "creation and update timestamps should be valid dates",
    () => {
      const createdDate = new Date(createdTodo.created_at);
      const updatedDate = new Date(createdTodo.updated_at);
      return !isNaN(createdDate.getTime()) && !isNaN(updatedDate.getTime());
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUserListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserListUser";
import type { ITodoListUserTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserTodo";

export async function test_api_todo_deletion_by_owner(
  connection: api.IConnection,
) {
  // Step 1: Register a new user account
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "Password123!";
  const userJoinBody = {
    email: userEmail,
    password: userPassword,
  } satisfies ITodoListUserListUser.IJoin;

  const user: ITodoListUserListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: userJoinBody,
    });
  typia.assert(user);
  TestValidator.equals("user email matches", user.email, userEmail);

  // Step 2: Create a todo item for the user
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies ITodoListUserTodo.ICreate;

  const todo: ITodoListUserTodo =
    await api.functional.todoList.user.users.todos.create(connection, {
      userId: user.id,
      body: todoCreateBody,
    });
  typia.assert(todo);
  TestValidator.equals("todo title matches", todo.title, todoCreateBody.title);
  TestValidator.equals("todo owner matches", todo.todo_list_user_id, user.id);
  TestValidator.predicate("todo is not deleted", () => !todo.deleted_at);

  // Step 3: Delete the todo item by its owner
  const deletedTodo: ITodoListUserTodo =
    await api.functional.todoList.user.users.todos.erase(connection, {
      userId: user.id,
      todoId: todo.id,
    });
  typia.assert(deletedTodo);

  // Step 4: Verify the deleted todo has populated deleted_at timestamp
  TestValidator.equals("deleted todo ID matches", deletedTodo.id, todo.id);
  TestValidator.equals(
    "deleted todo title matches",
    deletedTodo.title,
    todo.title,
  );
  TestValidator.equals(
    "deleted todo owner matches",
    deletedTodo.todo_list_user_id,
    user.id,
  );
  TestValidator.predicate(
    "deleted todo has deletion timestamp",
    () =>
      deletedTodo.deleted_at !== null &&
      deletedTodo.deleted_at !== undefined &&
      new Date(deletedTodo.deleted_at) instanceof Date,
  );

  // Step 5: Verify that subsequent attempts to retrieve the item return appropriate error responses
  // Note: The scenario doesn't specify a retrieval endpoint, so we can't test this part directly
  // However, we can test that the deletion endpoint properly prevents double deletion
  await TestValidator.error("cannot delete already deleted todo", async () => {
    await api.functional.todoList.user.users.todos.erase(connection, {
      userId: user.id,
      todoId: todo.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUserListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserListUser";

export async function test_api_user_login_invalid_credentials(
  connection: api.IConnection,
) {
  // First, create a user account to test against
  const joinInput = {
    email: `test-${RandomGenerator.alphabets(10)}@example.com`,
    password: `password-${RandomGenerator.alphabets(15)}`,
  } satisfies ITodoListUserListUser.IJoin;

  const user = await api.functional.auth.user.join(connection, {
    body: joinInput,
  });
  typia.assert(user);

  // Test 1: Login with wrong email but correct password
  await TestValidator.error(
    "should reject login with wrong email",
    async () => {
      await api.functional.auth.user.login(connection, {
        body: {
          email: `wrong-${RandomGenerator.alphabets(10)}@example.com`,
          password: joinInput.password,
          href: `${connection.host}/login`,
          referrer: `${connection.host}/`,
          ip: "127.0.0.1",
        } satisfies ITodoListUserListUser.ILogin,
      });
    },
  );

  // Test 2: Login with correct email but wrong password
  await TestValidator.error(
    "should reject login with wrong password",
    async () => {
      await api.functional.auth.user.login(connection, {
        body: {
          email: joinInput.email,
          password: `wrong-${RandomGenerator.alphabets(15)}`,
          href: `${connection.host}/login`,
          referrer: `${connection.host}/`,
          ip: "127.0.0.1",
        } satisfies ITodoListUserListUser.ILogin,
      });
    },
  );

  // Test 3: Login with both wrong email and password
  await TestValidator.error(
    "should reject login with wrong email and password",
    async () => {
      await api.functional.auth.user.login(connection, {
        body: {
          email: `wrong-${RandomGenerator.alphabets(10)}@example.com`,
          password: `wrong-${RandomGenerator.alphabets(15)}`,
          href: `${connection.host}/login`,
          referrer: `${connection.host}/`,
          ip: "127.0.0.1",
        } satisfies ITodoListUserListUser.ILogin,
      });
    },
  );

  // Test 4: Verify that correct credentials still work
  const validLogin = await api.functional.auth.user.login(connection, {
    body: {
      email: joinInput.email,
      password: joinInput.password,
      href: `${connection.host}/login`,
      referrer: `${connection.host}/`,
      ip: "127.0.0.1",
    } satisfies ITodoListUserListUser.ILogin,
  });
  typia.assert(validLogin);
  TestValidator.equals(
    "valid login should return user ID",
    validLogin.id,
    user.id,
  );
  TestValidator.equals(
    "valid login should return user email",
    validLogin.email,
    user.email,
  );
}

