import { ITodoListUserListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoListUserListUser.ILogin;
}): Promise<ITodoListUserListUser.IAuthorized> {
  // 1. Find user by email
  const user = await MyGlobal.prisma.todo_list_users.findFirst({
    where: { email: props.body.email },
  });

  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // 2. Verify password
  const isValid = await PasswordUtil.verify(props.body.password, user.password);

  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // 3. Create new session
  const now = new Date();
  const accessExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(now.getTime() + 60 * 60 * 1000),
  );
  const refreshExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000),
  );

  const session = await MyGlobal.prisma.todo_list_user_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_list_user_id: user.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(now),
      expired_at: accessExpires,
    },
  });

  // 4. Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  // 5. Return authorized user information
  return {
    id: user.id,
    email: user.email,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUserListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postAuthUserRefresh(props: {
  user: UserPayload;
}): Promise<ITodoListUserListUser.IAuthorized> {
  // Get the user and session information from the payload
  const { id, session_id } = props.user;

  // Validate session exists and is active
  const session = await MyGlobal.prisma.todo_list_user_sessions.findFirst({
    where: {
      id: session_id,
      todo_list_user_id: id,
    },
    include: {
      user: true,
    },
  });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  } else if (session.user.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  // Generate new access and refresh tokens with same session ID
  const now = Date.now();
  const accessExpiresTimestamp = now + 60 * 60 * 1000; // 1 hour
  const refreshExpiresTimestamp = now + 7 * 24 * 60 * 60 * 1000; // 7 days

  const accessExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(accessExpiresTimestamp),
  );
  const refreshExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(refreshExpiresTimestamp),
  );

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: id,
        session_id: session_id,
        created_at: new Date().toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: id,
        session_id: session_id,
        tokenType: "refresh",
        created_at: new Date().toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  // Update session expiration time
  await MyGlobal.prisma.todo_list_user_sessions.update({
    where: {
      id: session_id,
    },
    data: {
      expired_at: new Date(refreshExpiresTimestamp),
    },
  });

  // Return authorized user information with new tokens
  return {
    id: session.user.id,
    email: session.user.email,
    token: token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUserTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserTodo";
import { IPageITodoListUserTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUserTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoListUserTodos(props: {
  user: UserPayload;
  body: ITodoListUserTodo.IRequest;
}): Promise<IPageITodoListUserTodo.ISummary> {
  // Set default values for pagination parameters
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  // Build where condition for user's todos excluding deleted ones
  const whereCondition = {
    todo_list_user_id: props.user.id,
    deleted_at: null,
  };

  // Execute findMany and count operations concurrently
  const [todos, total] = await Promise.all([
    MyGlobal.prisma.todo_list_todos.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy: {
        created_at: "desc",
      },
    }),
    MyGlobal.prisma.todo_list_todos.count({
      where: whereCondition,
    }),
  ]);

  // Transform todos to match the ISummary interface
  const data = todos.map((todo) => ({
    id: todo.id,
    title: todo.title,
    completed: todo.completed,
    created_at: toISOStringSafe(todo.created_at),
    updated_at: toISOStringSafe(todo.updated_at),
  }));

  // Calculate pagination information
  const pagination: IPage.IPagination = {
    current: page,
    limit: limit,
    records: total,
    pages: Math.ceil(total / limit),
  };

  // Return the paginated response
  return {
    data,
    pagination,
  };
}

